import base64,csv,hashlib,io,json,re
from pathlib import Path
root=Path('products/services/canadabuys-offline-reconciliation'); raw=base64.b64decode((root/'raw/new-tender-notices.csv.b64').read_bytes()); reader=csv.DictReader(io.StringIO(raw.decode('utf-8-sig'),newline='')); rows=list(reader); keys=reader.fieldnames or []; descriptions=[k for k in keys if k.lower().startswith(('description','tenderdescription','noticedescription'))]; links=[k for k in keys if ('url' in k.lower() or 'link' in k.lower()) and ('notice' in k.lower() or 'tender' in k.lower())]; pattern=re.compile(r'\b(?:csv|xlsx|spreadsheet|reconcil\w*|data (?:cleansing|cleaning|validation|migration|quality)|validat\w* (?:des|de) donn[ée]es|rapprochement|tableur|migration de donn[ée]es)\b',re.I); hits=[]
