        hits.append({'title':row.get('title-titre-eng'),'ref':row.get('referenceNumber-numeroReference'),'closing':row.get('tenderClosingDate-appelOffresDateCloture'),'source_links':{k:row.get(k) for k in links if row.get(k)},'excerpts':excerpts})
result={'sha256':hashlib.sha256(raw).hexdigest(),'rows':len(rows),'description_fields':descriptions,'rows_with_description':sum(any((r.get(k) or '').strip() for k in descriptions) for r in rows),'hits':hits,'scope':'Keyword triage only. Original buyer terms determine current deadline, eligibility and whether the work is separately quotable.'}; target=root/'director-new-notice-description-screen.json'; target.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); print(json.dumps({'rows':len(rows),'description_fields':descriptions,'candidate_titles':[h['title'] for h in hits]},ensure_ascii=False))
